mapper.select:
SELECT bbs11_application_id AS application_id, bbs11_company_id AS company_id, bbs11_app_date AS app_date, bbs11_app_emp_id AS app_emp_id, f_emp_kor_nm(bbs11_app_emp_id) AS app_emp_name, bbs11_app_type AS app_type, f_cdnm('ApplicationType', bbs11_app_type, bbs11_company_id, f_sysdate()) AS app_type_name, bbs11_app_status AS app_status, f_cdnm('ApplicationStatusCode', bbs11_app_status, bbs11_company_id, f_sysdate()) AS app_status_name, bbs11_close_date AS close_date, bbs11_note AS note, bbs11_content AS content FROM bbs11_application WHERE bbs11_company_id = #{cond.companyId} AND bbs11_app_date BETWEEN #{cond.startDate} AND #{cond.closeDate}
AND bbs11_app_type = #{cond.appTypeCode}
AND bbs11_close_date IS NULL
ORDER BY bbs11_app_date DESC, bbs11_app_type

mapper.update:
UPDATE bbs11_application
   SET bbs11_app_status = #{req.appStatus}
     , bbs11_close_date = #{req.closeDate}
     , bbs11_note       = #{req.note}
 WHERE bbs11_application_id = #{req.applicationId}
   AND bbs11_company_id     = #{companyId}

UPDATE bbs11_application
   SET bbs11_content = #{content}
 WHERE bbs11_application_id = #{applicationId}
   AND bbs11_company_id     = #{companyId}

